# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

OPEN = parse_span("09:00-17:00")


def spans(*texts):
    return [parse_span(text) for text in texts]


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        work = spans("09:00-12:00", "13:00-17:00")
        self.assertEqual(
            find_gaps(work, OPEN),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        work = spans("10:00-16:00")
        self.assertEqual(
            find_gaps(work, OPEN),
            ["gap 09:00-10:00 (60 min)",
             "gap 16:00-17:00 (60 min)"]
        )

    def test_overlaps_leave_no_gap(self):
        work = spans("09:00-13:00", "12:00-17:00")
        self.assertEqual(find_gaps(work, OPEN), [])

    def test_nobody_working(self):
        self.assertEqual(
            find_gaps([], parse_span("09:00-10:30")),
            ["gap 09:00-10:30 (90 min)"]
        )

    def test_span_outside_opening_hours(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("08:00-10:00"), OPEN)
        with self.assertRaises(ValueError):
            find_gaps(spans("16:00-18:00"), OPEN)


if __name__ == "__main__":
    unittest.main()
